function compareRows(matrix: number[][]) {
  let score = 0
  for (let row = 0; row < matrix.length; row += 1) {
    for (let col = 0; col < matrix[row].length; col += 1) {
      if (matrix[row][col] % 2 === 0) score += 1
    }
  }
  return score
}
