function sortThenScan(items: number[]) {
  items.sort((a, b) => a - b)
  let unique = 0
  for (let i = 0; i < items.length; i += 1) {
    if (i === 0 || items[i] !== items[i - 1]) unique += 1
  }
  return unique
}
