function mergeKinda(items: number[]) {
  if (items.length <= 1) return items
  const mid = Math.floor(items.length / 2)
  const left = mergeKinda(items.slice(0, mid))
  const right = mergeKinda(items.slice(mid))
  return merge(left, right)
}
