function fourChecks(items: number[]) {
  let c1 = 0
  for (const value of items) c1 += value > 0 ? 1 : 0
  let c2 = 0
  for (const value of items) c2 += value < 0 ? 1 : 0
  let c3 = 0
  for (const value of items) c3 += value === 0 ? 1 : 0
  let c4 = 0
  for (const value of items) c4 += value % 2 === 0 ? 1 : 0
  return c1 + c2 + c3 + c4
}
