function longestOnesAfterFlip(bits) {
  // Case S03Q1
  let left = 0;
  let zeros = 0;
  let best = 0;
  for (let right = 0; right < bits.length; right++) {
    if (bits[right] === 0) zeros++;
    while (zeros > 1) {
      if (bits[left] === 0) zeros--;
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}
