function wordsFromText(text) {
  // Case S13Q6
  const words = [];
  let cur = "";
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === " ") {
      if (cur.length) words.push(cur);
      cur = "";
    } else {
      cur += ch;
    }
  }
  if (cur.length) words.push(cur);
  return words;
}
