function twoStageGuardrails(items: number[]) {
  let valid = 0
  for (const value of items) if (Number.isFinite(value)) valid += 1

  let bounded = 0
  for (const value of items) if (value >= -1_000 && value <= 1_000) bounded += 1

  return valid + bounded
}
