function fiveStagePipeline(items: number[]) {
  let a = 0
  for (const value of items) a += value
  let b = 0
  for (const value of items) b += value * 2
  let c = 0
  for (const value of items) c += value > 100 ? 1 : 0
  let d = 0
  for (const value of items) d += value < -100 ? 1 : 0
  let e = 0
  for (const value of items) e += value === 0 ? 1 : 0
  return a + b + c + d + e
}
