function bfsAll(start, adj) {
  // Case S03Q2
  const q = [start];
  const seen = new Set([start]);
  let head = 0;
  while (head < q.length) {
    const node = q[head++];
    for (const nxt of adj[node]) {
      if (seen.has(nxt)) continue;
      seen.add(nxt);
      q.push(nxt);
    }
  }
  return seen.size;
}
