function topoSortKahnLinear(adj, indegree) {
  // Case S04Q1
  const q = [];
  for (let i = 0; i < indegree.length; i++) {
    if (indegree[i] === 0) q.push(i);
  }

  let head = 0;
  const order = [];
  while (head < q.length) {
    const node = q[head++];
    order.push(node);
    for (const nxt of adj[node]) {
      indegree[nxt]--;
      if (indegree[nxt] === 0) q.push(nxt);
    }
  }

  return order;
}
