function invertTreeIterative(root) {
  // Case S04Q3
  if (!root) return null;
  const q = [root];
  let head = 0;

  while (head < q.length) {
    const node = q[head++];
    const t = node.left;
    node.left = node.right;
    node.right = t;

    if (node.left) q.push(node.left);
    if (node.right) q.push(node.right);
  }

  return root;
}
