function cloneGraphBfs(start) {
  // Case S05Q1
  if (!start) return null;
  const map = new Map();
  const q = [start];
  let head = 0;
  map.set(start, { val: start.val, neighbors: [] });

  while (head < q.length) {
    const node = q[head++];
    const copy = map.get(node);
    for (const nei of node.neighbors) {
      if (!map.has(nei)) {
        map.set(nei, { val: nei.val, neighbors: [] });
        q.push(nei);
      }
      copy.neighbors.push(map.get(nei));
    }
  }

  return map.get(start);
}
