function overlapCountLinear(sortedIntervals) {
  // Case S05Q3
  if (sortedIntervals.length === 0) return 0;
  let overlaps = 0;
  let currentEnd = sortedIntervals[0][1];

  for (let i = 1; i < sortedIntervals.length; i++) {
    const [start, end] = sortedIntervals[i];
    if (start <= currentEnd) overlaps++;
    currentEnd = Math.max(currentEnd, end);
  }

  return overlaps;
}
