function scheduleByArrival(arrivals) {
  // Case S07Q2
  const q = [];
  let time = 0;
  for (let i = 0; i < arrivals.length; i++) {
    const job = arrivals[i];
    if (job.start > time) time = job.start;
    q.push(job);
    while (q.length && q[0].start <= time) {
      const cur = q.shift();
      time += cur.duration;
    }
  }
  while (q.length) time += q.shift().duration;
  return time;
}
