function undoableTextReplay(commands) {
  // Case S07Q3
  const text = [];
  const history = [];
  for (let i = 0; i < commands.length; i++) {
    const c = commands[i];
    if (c.type === "append") {
      text.push(c.ch);
      history.push(c);
    } else if (c.type === "delete" && text.length) {
      const ch = text.pop();
      history.push({ type: "restore", ch });
    } else if (c.type === "undo" && history.length) {
      const last = history.pop();
      if (last.type === "append" && text.length) text.pop();
      else if (last.type === "restore") text.push(last.ch);
    }
  }
  return text.join("");
}
