function indegreeZeroQueue(adj) {
  // Case S07Q5
  const n = adj.length;
  const indeg = new Array(n).fill(0);
  for (let u = 0; u < n; u++) {
    for (const v of adj[u]) indeg[v]++;
  }

  const q = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) q.push(i);

  let processed = 0;
  let head = 0;
  while (head < q.length) {
    const u = q[head++];
    processed++;
    for (const v of adj[u]) {
      indeg[v]--;
      if (indeg[v] === 0) q.push(v);
    }
  }

  return processed;
}
