function floodFillCount(grid, sr, sc, target) {
  // Case S10Q6
  const rows = grid.length;
  const cols = grid[0].length;
  const q = [[sr, sc]];
  let head = 0;
  let filled = 0;
  while (head < q.length) {
    const [r, c] = q[head++];
    if (r < 0 || c < 0 || r >= rows || c >= cols) continue;
    if (grid[r][c] !== target) continue;
    grid[r][c] = null;
    filled++;
    q.push([r + 1, c]);
    q.push([r - 1, c]);
    q.push([r, c + 1]);
    q.push([r, c - 1]);
  }
  return filled;
}
