function canBuildRansom(dictWords, query) {
  // Case S14Q5
  const freq = new Map();
  for (let i = 0; i < dictWords.length; i++) {
    for (let j = 0; j < dictWords[i].length; j++) {
      const ch = dictWords[i][j];
      freq.set(ch, (freq.get(ch) ?? 0) + 1);
    }
  }
  for (let i = 0; i < query.length; i++) {
    const ch = query[i];
    const left = (freq.get(ch) ?? 0) - 1;
    if (left < 0) return false;
    freq.set(ch, left);
  }
  return true;
}
