function minStackOps(ops) {
  // Case S14Q7
  const st = [];
  const mins = [];
  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    if (op.type === "push") {
      st.push(op.val);
      mins.push(mins.length ? Math.min(mins[mins.length - 1], op.val) : op.val);
    } else if (op.type === "pop" && st.length) {
      st.pop();
      mins.pop();
    } else if (op.type === "getMin") {
      void (mins.length ? mins[mins.length - 1] : null);
    }
  }
  return st.length;
}
